import {
  _decorator,
  Canvas,
  Component,
  director,
  Node,
  UITransform,
  Vec3,
} from "cc";
const { ccclass, property } = _decorator;

@ccclass("Ground")
export class Ground extends Component {
  @property({
    type: Node,
    tooltip: "Ground1 is here",
  })
  public ground1: Node;

  @property({
    type: Node,
    tooltip: "Ground2 is here",
  })
  public ground2: Node;

  @property({
    type: Node,
    tooltip: "Ground3 is here",
  })
  public ground3: Node;

  //Create ground width variable
  public groundWidth1: number;
  public groundWidth2: number;
  public groundWidth3: number;

  public tempStartLocation1 = new Vec3();
  public tempStartLocation2 = new Vec3();
  public tempStartLocation3 = new Vec3();

  public gameSpeed: number = 50;

  onLoad() {
    this.startUp(); //method
  }

  startUp() {
    this.groundWidth1 = this.ground1.getComponent(UITransform).width;
    this.groundWidth2 = this.ground2.getComponent(UITransform).width;
    this.groundWidth3 = this.ground3.getComponent(UITransform).width;

    this.tempStartLocation1.x = 0;
    this.tempStartLocation2.x = this.groundWidth1;
    this.tempStartLocation3.x = this.groundWidth1 + this.groundWidth2;

    this.ground1.setPosition(this.tempStartLocation1);
    this.ground2.setPosition(this.tempStartLocation2);
    this.ground3.setPosition(this.tempStartLocation3);
  }

  start() {}

  update(deltaTime: number) {
    this.tempStartLocation1 = this.ground1.position;
    this.tempStartLocation2 = this.ground2.position;
    this.tempStartLocation3 = this.ground3.position;

    //motion of base
    this.tempStartLocation1.x -= this.gameSpeed * deltaTime;
    this.tempStartLocation2.x -= this.gameSpeed * deltaTime;
    this.tempStartLocation3.x -= this.gameSpeed * deltaTime;

    //get the scene
    const scene = director.getScene();
    const canvas = scene.getComponentInChildren(Canvas);
    const width = canvas.getComponent(UITransform).width;

    //realigning the base
    if (this.tempStartLocation1.x + this.groundWidth1 < 0) {
      //align to end
      this.tempStartLocation1.x = width;
    }

    if (this.tempStartLocation2.x + this.groundWidth2 < 0) {
      //align to end
      this.tempStartLocation2.x = width;
    }

    if (this.tempStartLocation3.x + this.groundWidth3 < 0) {
      //align to end
      this.tempStartLocation3.x = width;
    }

    this.ground1.setPosition(this.tempStartLocation1);
    this.ground2.setPosition(this.tempStartLocation2);
    this.ground3.setPosition(this.tempStartLocation3);
  }
}